{{template "top" .}}<section class="fl-track"><div class="wrap">
<div class="track-head"><span class="eyebrow">{{.title}}</span><h1 id="status" aria-live="polite">{{.statusText}}</h1><p>{{.intro}}</p></div>
<div class="fl-grid"><div class="fl-mapcol"><div class="map-box"><div id="map" role="region" aria-label="{{.t.map_label}}"></div></div>
<div class="fl-meter" id="meter"{{if not .sample}} hidden{{end}}><div class="fl-meter-bar"><i id="meter-fill"></i></div><p id="meter-text">{{if .sample}}{{.t.sample_note}}{{end}}</p></div></div>
<aside class="fl-side">
<ol class="fl-steps" id="steps" data-status="{{.status}}" aria-label="{{.t.steps_label}}">{{range .steps}}<li data-step="{{.value}}"{{if .done}} class="done"{{end}}{{if .current}} aria-current="step"{{end}}><span class="dot" aria-hidden="true"></span>{{.label}}</li>{{end}}</ol>
<p class="seen" id="seen">{{if .seen}}<time datetime="{{.updated}}Z">{{.seen}}</time>{{else if not .hasPos}}{{.t.waiting}}{{end}}</p>
{{if .sample}}<button class="btn wide" id="sim" type="button">{{.t.simulate}}</button>{{end}}
<dl class="fl-order">{{with .item}}<div><dt>{{$.t.order_label}}</dt><dd>{{.}}</dd></div>{{end}}
<div><dt>{{.t.deliver_to}}</dt><dd>{{.customer}}{{with .dropoff}}<br><span>{{.}}</span>{{end}}</dd></div>
{{with .window}}<div><dt>{{$.t.window_label}}</dt><dd>{{.}}</dd></div>{{end}}</dl>
{{if .tel}}<div class="help"><p>{{.t.questions}}</p><a href="tel:{{.tel}}">{{.t.call_us}} <bdi dir="ltr">{{.phone}}</bdi></a></div>{{end}}</aside></div></div></section>
<script>
(function(){
var names={{.statusNames}},order=["preparing","on_the_way","delivered"],tx={{.js}};
var start=[{{.lat}},{{.lng}}],has={{.hasPos}},shopAt={{.shopAt}},dest={{.dest}},route={{.route}},sample={{.sample}};
var d=document,statusEl=d.getElementById("status"),list=d.getElementById("steps"),seen=d.getElementById("seen");
var reduce=!!(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches);
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function clock(){return new Date().toLocaleTimeString(tx.locale,{hour:"2-digit",minute:"2-digit",hourCycle:"h23"})}
// Status heading and progress list.
function setStatus(s){statusEl.textContent=names[s]||s;var i=order.indexOf(s);list.setAttribute("data-status",s);
 Array.prototype.forEach.call(list.children,function(li,n){li.classList.toggle("done",n<i);if(n===i)li.setAttribute("aria-current","step");else li.removeAttribute("aria-current")})}
// The map, when Leaflet loaded: the shop, the drop-off, the route and the courier.
var map=null,marker=null,brand=getComputedStyle(d.documentElement).getPropertyValue("--brand").trim()||"#a33a5c";
function pinIcon(cls,label){return L.divIcon({className:"fl-pin "+cls,html:"<span>"+esc(label)+"</span>",iconSize:[30,30],iconAnchor:[15,15]})}
function courierAt(p){if(!map)return;if(!marker)marker=L.marker(p,{icon:L.divIcon({className:"courier-pin",iconSize:[22,22]}),title:tx.courier,keyboard:false,zIndexOffset:1000}).addTo(map);else marker.setLatLng(p)}
if(window.L){
 map=L.map("map",{scrollWheelZoom:false}).setView(has?start:(dest||shopAt||[25.2048,55.2708]),has?15:12);
 map.attributionControl.setPrefix(false);
 L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">'+esc(tx.osm_credit)+"</a>"}).addTo(map);
 var pts=[];
 if(route&&route.length>1&&L.polyline){L.polyline(route,{color:brand,weight:4,opacity:.75,dashArray:"2 9",lineCap:"round"}).addTo(map);pts=pts.concat(route)}
 if(shopAt){L.marker(shopAt,{icon:pinIcon("shop","✿"),title:tx.shop_pin,keyboard:false}).addTo(map);pts.push(shopAt)}
 if(dest){L.marker(dest,{icon:pinIcon("home","⌂"),title:tx.dropoff_pin,keyboard:false}).addTo(map);pts.push(dest)}
 if(has){courierAt(start);pts.push(start)}
 if(pts.length>1&&map.fitBounds)map.fitBounds(pts,{padding:[36,36],maxZoom:15});
}
// Live updates from the courier's phone (samples too, so the courier page can be tried).
if({{.token}}){var live=new EventSource('/_rx/live/{{.channel}}?token='+encodeURIComponent({{.token}}));
 live.onmessage=function(e){var m=JSON.parse(e.data);
  if(m.status){setStatus(m.status);if(m.status==="delivered")live.close()}
  if(typeof m.lat==="number"){var p=[m.lat,m.lng];if(map&&!marker)map.setView(p,15);courierAt(p);if(map)map.panTo(p);
   seen.textContent=tx.seen_live.replace("{time}",new Date().toLocaleTimeString(tx.locale,{hour:"2-digit",minute:"2-digit",second:"2-digit",hourCycle:"h23"}))}}}
// Samples: a courier drives the route in this browser only; nothing is saved.
var sim=d.getElementById("sim");
if(sim&&route&&route.length>1){
 var R=6371,rad=Math.PI/180,cum=[0];
 function dist(a,b){var dl=(b[0]-a[0])*rad,dg=(b[1]-a[1])*rad,x=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(a[0]*rad)*Math.cos(b[0]*rad)*Math.sin(dg/2)*Math.sin(dg/2);return 2*R*Math.asin(Math.sqrt(x))}
 for(var i=1;i<route.length;i++)cum.push(cum[i-1]+dist(route[i-1],route[i]));
 var total=cum[cum.length-1],fill=d.getElementById("meter-fill"),mtext=d.getElementById("meter-text"),timer=null,raf=0;
 function at(km){for(var i=1;i<cum.length;i++)if(km<=cum[i]){var f=(km-cum[i-1])/((cum[i]-cum[i-1])||1),a=route[i-1],b=route[i];return [a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}return route[route.length-1]}
 function show(t){var left=Math.max(0,total*(1-t));fill.style.width=(t*100).toFixed(1)+"%";
  mtext.textContent=tx.km_left.replace("{km}",left.toFixed(1)).replace("{min}",Math.max(1,Math.ceil(left/0.45)))}
 function stop(){clearTimeout(timer);cancelAnimationFrame(raf)}
 sim.onclick=function(){stop();sim.disabled=true;setStatus("preparing");seen.textContent=tx.sim_preparing;fill.style.width="0%";mtext.textContent=tx.sim_preparing;courierAt(route[0]);
  timer=setTimeout(function(){setStatus("on_the_way");seen.textContent=tx.sim_live;
   var dur=Math.min(30000,Math.max(12000,total*1800)),t0=null,steps=reduce?6:0,k=0;
   function done(){courierAt(route[route.length-1]);show(1);setStatus("delivered");var at=tx.arrived.replace("{time}",clock());seen.textContent=at;mtext.textContent=at;sim.disabled=false;sim.textContent=tx.simulate_again}
   if(steps){(function jump(){k++;var t=k/steps;courierAt(at(total*t));show(t);if(k<steps)timer=setTimeout(jump,900);else done()})();return}
   (function frame(ts){if(t0===null)t0=ts;var t=Math.min(1,(ts-t0)/dur),e=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;courierAt(at(total*e));show(e);if(t<1)raf=requestAnimationFrame(frame);else done()})(performance.now());
  },reduce?600:1600)};
}
})();
</script>{{template "bottom" .}}

