}
// [lat, lng] when both are numbers, else null.
function point(lat, lng) { return typeof lat === 'number' && typeof lng === 'number' ? [lat, lng] : null; }
// The path a sample's simulated courier drives: the route column (a JSON list of [lat, lng]) when it has two
// points or more, else straight from the shop to the drop-off when both are known, else none.
function routeOf(d, shopAt, dest) {
  let r = [];
  try { r = typeof d.route === 'string' && d.route ? JSON.parse(d.route) : (Array.isArray(d.route) ? d.route : []); } catch (e) { r = []; }
  r = (Array.isArray(r) ? r : []).filter(p => Array.isArray(p) && typeof p[0] === 'number' && typeof p[1] === 'number').slice(0, 200);
  if (r.length >= 2) return r;
